#[madsim::test]
async fn delayed_snapshot_consumer_keeps_ordered_prefix() {
    let runtime = Handle::current();
    let peers: Vec<SocketAddr> = (1..=3).map(|i| ([10, 252, 0, i], 1).into()).collect();
    let mut nodes = vec"'![];
